/* assets/i18n/elliptic-curve-diffie-hellman.js — the 'ecdh' namespace: title/
   heading/lede (rich, with a cross-link to the Diffie-Hellman Key Exchange
   page), the intro panel (rich), field labels (incl. the k_A/k_B rich
   labels), the small-subgroup caution chip, Build exchange/Randomize
   private scalars, the curve SVG aria-label, legend, section headings, the
   Eve avatar row's trailing label, the discrete-log panel, the group-law
   explorer's hint/colors/readout/log text, footer, every validation
   message, the per-step banner captions (ecdh.step.*), the arithmetic log's
   per-step headings/formulas (built as DOM nodes and rendered through
   translateInto, never innerHTML), Eve's notebook, her brute-force result
   boxes, the base-point dropdown's per-option template, the curve point
   dots' aria-label template, and the field's midline/infinity captions, for
   the Elliptic Curve Diffie-Hellman tool, in all twenty-seven supported languages.

   Classic script, IIFE, "use strict" — its only statement is
   NT.i18n.register(...). Pure math notation (p, a, b, G, A, B, k_A, k_B,
   point coordinates, "mod", "=", curve/line equations) is written
   identically in every language per 06-GLOSSARY.md section (e) and is
   built directly in the page script with no dictionary key. "ord(G)"'s
   abbreviated word ("ord") is NOT in that notation list and is translated
   per language via `ordWord` (mirroring the Diffie-Hellman Key Exchange
   page's `orderLabel` fix) -- kept as English's pre-existing literal "ord"
   only in the en column, since a literal shared across languages made the
   whole rendered segment byte-identical to English regardless of the
   numeric value it wraps. Alice, Bob and
   Eve are proper nouns kept identical in every language per
   06-GLOSSARY.md section (d) — Eve is never localized to "Ève"/"Eva".
   Play/Step/Instant/Reset live in the shared `common` namespace
   (assets/i18n/site.js); Build exchange and Randomize private scalars are
   page-specific keys here. `dhLinkText` duplicates the Diffie-Hellman Key
   Exchange page's own `dh.heading` translations byte-for-byte per language
   (a page namespace may not reference another page's namespace — FOREIGN-NS
   — so the string is copied here rather than referenced). Must load after
   assets/nt-i18n.js and assets/i18n/site.js, before the page's own inline
   <script>.
*/
