      lede: 'Cały zbiór punktów małej krzywej eliptycznej nad ciałem pierwszym, naniesiony jako rozrzut punktów. Alice i Bob przechodzą przez niego za pomocą mnożenia przez skalar i trafiają w ten sam punkt z przeciwnych stron — ten sam protokół co {0}, w grupie, której elementami są punkty, a nie liczby.',
      dhLinkText: 'Wymiana kluczy Diffiego-Hellmana',
      introHeading: 'Jak to działa',
      introP1: 'Krzywa {0} ma zbiór punktów, który tworzy grupę: wybierz dwa punkty, narysuj przechodzącą przez nie linię, a ta linia przecina krzywą w dokładnie jednym kolejnym punkcie — odbij ten punkt względem horyzontalnej linii środkowej i masz ich sumę. Mnożenie przez skalar kG oznacza dodawanie G do samego siebie k razy przy użyciu tej konstrukcji. {1} wybiera tajny skalar a i oblicza A = aG; {2} wybiera b i oblicza B = bG. Wymieniają A i B jawnie, a potem każde z nich mnoży otrzymaną wartość przez swój własny tajny skalar — aB i bA trafiają w dokładnie ten sam punkt, wspólny sekret, nawet jeśli {3} widziała, jak A i B przechodzą przez linię.',
