      lede: 'Seti nzima ya nukta za mkunjo duaradufu mdogo juu ya uwanja wa namba tasa, iliyochorwa kama mtawanyiko. Alice na Bob wanatembea juu yake kwa kuzidisha kwa skala na kutua kwenye nukta ile ile kutoka pande tofauti — itifaki ile ile kama zana ya {0}, katika kundi ambalo vipengele vyake ni nukta badala ya namba.',
